return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'sah','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:07+00:00','po-revision-date'=>'2026-11-05T19:51:07+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Сайтыҥ эрдэттэн туруоруллубут плагиннарыгар уонна тиэмэлэригэр суох тылбаастары толорор.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Бу хачайдаан экрана эргэрбит: онтон ыла атын хачайдааһын бэлэмнэммит. Туох даҕаны ыытыллыбата. Билиҥҥитин Тылбаас испииһэгиттэн көр.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Босхо сулууспа былаана хас биирдии сайтка плагиннарга уонна тиэмэлэргэ хааччахтаах ахсааннаах слотары биэрэр; туттуллар слотар Babilim-ы холбообуккуттан кэннэ Settings-ка көстөллөр.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Тылбаастатарга көрдөһүү бу плагины эбэтэр тиэманы бу сайт босхо сулууспа былаанын слотарыттан биирдэстэригэр тиксэрэр (хааччах: тиэмэҕэ %1$d, плагиҥҥа %2$d), урукку слота суох буоллаҕына. Слот туттуллубут быһыытынан хаалар, табыллыбатах тылбаас эмиэ босотуо суоҕа.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Тылбаастатарга көрдөһүү бу плагины эбэтэр тиэманы бу сайт босхо сулууспа былаанын слотарыттан биирдэстэригэр тиксэрэр, урукку слота суох буоллаҕына. Слот туттуллубут быһыытынан хаалар, табыллыбатах тылбаас эмиэ босотуо суоҕа.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Бу плагин эбэтэр тиэма бу сайт босхо сулууспа былаанын слотарыгар өссө суох буоллаҕына, тылбаастатарга көрдөһүү кинини биирдэстэригэр тиксэрэр (хааччах: тиэмэҕэ %1$d, плагиҥҥа %2$d). Слот туттуллубут быһыытынан хаалар, табыллыбатах тылбаас эмиэ босотуо суоҕа. Салҕыыбыт дуо?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Бу плагин эбэтэр тиэма бу сайт босхо сулууспа былаанын слотарыгар өссө суох буоллаҕына, тылбаастатарга көрдөһүү кинини биирдэстэригэр тиксэрэр. Слот туттуллубут быһыытынан хаалар, табыллыбатах тылбаас эмиэ босотуо суоҕа. Салҕыыбыт дуо?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Бу ситимҥэ %1$d сайт плагин сотуллубутугар Babilim идентификатын сотор гына туруорулунна. Ол сайтка холбоммут төлөбүрдээх лицензия кэлин аптамаатынан эргиллибэт; Babilim өйөбүлэ %2$s аадырыска сибээстэһиэхтээххин. Идентификаты хаалларарга «Cancel» диэни баттаа, ол сайт Babilim туруорууларыгар "Туох баарын Babilim дааннайдарын устарыгар сот" бэлиэни ыл, онтон плагины өссө төгүл арахсыт. Ол гынан баран арахсытыаххын баҕараҕын дуо?' . "\0" . 'Бу ситимҥэ %1$d сайт плагин сотуллубутугар Babilim идентификаттарын сотор гына туруорулунна. Ол сайтарга холбоммут төлөбүрдээх лицензиялар кэлин аптамаатынан эргиллибэттэр; Babilim өйөбүлэ %2$s аадырыска сибээстэһиэхтээххин. Идентификаттары хаалларарга «Cancel» диэни баттаа, хас биирдии сайт Babilim туруорууларыгар "Туох баарын Babilim дааннайдарын устарыгар сот" бэлиэни ыл, онтон плагины өссө төгүл арахсыт. Ол гынан баран арахсытыаххын баҕараҕын дуо?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s толоруллуохтаах үлэ суох.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Тылы тал.','%d failed'=>'%d табыллыбата' . "\0" . '%d табыллыбата','%d not yet tried'=>'%d өссө боруобаламмата' . "\0" . '%d өссө боруобаламмата','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d сибээс күүтэр. "Куруук үллэстии" уонна "Үллэспэт" барыларыгар туттуллаллар.' . "\0" . '%d сибээс күүтэр. "Куруук үллэстии" уонна "Үллэспэт" барыларыгар туттуллаллар.','%d skipped'=>'%d аһарылынна' . "\0" . '%d аһарылынна','%d succeeded'=>'%d ситиһиилээх' . "\0" . '%d ситиһиилээх','%d to install'=>'%d туруоруллар' . "\0" . '%d туруоруллар','(a public key generated for this site)'=>'(бу сайтка оҥоһуллубут аһаҕас ключ)','(detected)'=>'(көстүбүт)','(generic codes and coordinates only)'=>'(общай кодтар уонна координаттар эрэ)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Ыраастааһын %1$s тохтотуллубут: %2$s. Туох да устуллубата.','A file in the component could not be read, so it was not packaged.'=>'Компоненаҕа биир билэ ааҕыллыбата, онон пакеткэ киллэриллибэтэ.','A host that serves only one PHP request at a time cannot complete this step.'=>'Биир кэмҥэ биир эрэ PHP көрдөбүлүн толорор хостинг бу хардыыны түмүктээбэт.','A part of the upload kept failing, so the upload was cancelled.'=>'Ыытыы биир чааһа хаста да алдьанна, онон ыытыы тохтотулунна.','A translation cannot be requested for that locale on this site right now.'=>'Бу локаль иһин тылбаасты билигин маннык сайтка көрдөөн сатаммат.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Тылбаас индексыгар суруйуу %1$s (%2$s) атын көрдөбүлгэ утарыласпыта уонна туһаныллыбата; саамай бүтэһик барыла хаалла.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Тылбаас индекһыгар %1$s (%2$s) суруйуу түмүктэммэтэ уонна туһаныллыбата (%3$s).','Account'=>'Аккаунт','Add another language'=>'Атын тылы эбэргэ','Advanced'=>'Дириҥэтиллибит','All'=>'Бары','All free-plan slots for this site are used'=>'Бу сайт босхо тарифа слоттара барыта туттулла тураллар','All languages'=>'Бары тыллар','Already in WordPress core'=>'WordPress ядроҕар баар','Already installed.'=>'Урут туруоруллубут.','Always share'=>'Куруук үллэстии','Another installation is running; try again in a moment.'=>'Атын туруоруу бара турар; биир кэм кэнниттэн хос боруобалаа.','Automatic installs'=>'Автоматическай туруоруулар','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Автоматтыы туруоруу билигин араарылынна; баҕарар буоллаххына туруорууларга төттөрү үлэҕэ киллэр.','Available'=>'Баар','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Баар тылбаастары биир баттааһынынан туруоруохха, суохтарын көрдөөххө сөп. Аптамаатынан туруоруулар үлэлии турдахтарына, сиэрбис эн салайар тылларыҥ иһин баар диэн ыйбыт тылбаастара суукканы иккитэ синхроннааһын кэмигэр туруорулланаллар.','Available · %s'=>'Баар · %s','Babilim Settings'=>'Babilim туруоруулара','Babilim adds translations for every language checked here.'=>'Babilim манна бэлиэтэммит тыллар барыларыгар тылбаастары эбэр.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim сайтан тас болдьохтоох хаалбаһаны бигэргэтиэн кыайбата, ол иһин сорох ис чааһа пакеттаммата уонна туох да хачайдаммата. wp-config.php-ҥа BABILIM_TEMP_DIR диэни веб-тамыртан тас суруллар хаалбаһа курдук быһаар (холобур, сайтыҥ сүрүн хаалбаһатыгар иһигэр буолбакка, чугаһыгар баар хаалбаһа), эбэтэр хостингыттан көрдөс.','Babilim could not finish checking this site.'=>'Babilim бу сайты тутулуктаахтык бэрэбиэркэлээн бүтэрбэтэ.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim холбооһуну түмүктээбэтэ (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim бу сайты бигэргэтэн бүтэрбэтэ (сервис төттөру ситиспэтэ). Регистрация тохтотулунна.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim бу сайты бигэргэтэн көрбөтө, онон бигэргэтии ситиһиллэ илик буоллаҕына, туох да хачайдаммат уонна туруоруллубат.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim бу сайты бигэргэтэн көрбөтө, онон туох даҕаны хачайдаммат да, туруоруллубат да.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim бу сайтан эн тылгар тылбааһа суох плагиннары уонна тиэмэлэри булан, биирдии-биирдиилэригэр тылбаас туруорар.','Babilim has not been enabled for this site yet.'=>'Babilim бу сайтка өссө үлэлэтиллибэтэх.','Babilim has not installed any translation for this language.'=>'Babilim бу тыл иһин туох даҕаны тылбааһы туруорбатах.','Babilim hit an error. Share an error report?'=>'Babilim алҕастаата. Алҕас туһунан сибээһи үллэстиэххэ дуо?','Babilim installed %d translation automatically since your last visit.'=>'Бүтэһик кэлиигиттэн ыла Babilim %d тылбаһы автоматтыы туруорда.' . "\0" . 'Бүтэһик кэлиигиттэн ыла Babilim %d тылбаһы автоматтыы туруорда.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim араарыллыбыт. Ордук туох даҕаны ыытыллыбат; туруоруллубут тылбаастар үлэлииллэр.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim үлэҕэ киирдэ: бу сайт бигэргэннэ уонна %d компонент көстүбүтэ.' . "\0" . 'Babilim үлэҕэ киирдэ: бу сайт бигэргэннэ уонна %d компонент көстүбүтэ.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim бу сайты холбоон, бэрэбиэркэлии турар… (бүтэһик боруобалааһын: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim бу сайты холбоон, бэрэбиэркэлии турар… Бу сирэйи хат ыл эбэтэр былаанынан барар бэрэбиэркэ түмүктэниэр диэри кэтэс.','Babilim is not enabled.'=>'Babilim холбоммотох.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Плагин сотуллубутугар Babilim бу сайт идентификатын сотор гына туруорулунна. Бу сайтка холбоммут төлөбүрдээх лицензия кэлин аптамаатынан эргиллибэт; Babilim өйөбүлэ %s аадырыска сибээстэһиэхтээххин. Идентификаты хаалларарга «Cancel» диэни баттаа, Babilim туруорууларыгар "Туох баарын Babilim дааннайдарын устарыгар сот" бэлиэни ыл, онтон плагины өссө төгүл арахсыт. Ол гынан баран арахсытыаххын баҕараҕын дуо?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim бу этапка кэмэ түмүктэннэ, кэлэр бэрэбиэркэҕэ салгыыр.','Babilim settings'=>'Babilim туруорууллара','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim синхронизацията сервис өттүттэн кыратык хойутаата (көрдөбүллэр лимиттэрэ ааста); %s кэннэ хат боруобалыыр.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Бу хачайдааһын кэтэһэ турдаҕына Babilim саҥардылынна. Эргэ пакет быраҕылынна; хачайдааһыны төттөрү бигэргэт.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (барыла %2$s) диэнтэн бу билэлэри хачайдыыр: барыта .php уонна .js билэлэри, барыта block.json билэлэри, уонна сүрүн хаалбаһыгар баар readme.txt, readme.md, style.css уонна theme.json. Ону тылбаастыахтаах тиэкиһи булар уонна плагини эбэтэр тиэмэни быһаарар сыалтан туттар.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest туттар кыах суох: %s','Back'=>'Төннүү','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Бу домеҥҥа урут лицензия атыылаһан турдаҕыҥ дуо? Төлөөһүн кэмигэр ылбыккын Төттөрү төрүтүнэр коду киллэр.','Broken placeholder'=>'Алдьаммыт placeholder (оннуттан тутуллар бэлиэ)','Build'=>'Хостооһун','Built'=>'Оҥоһулунна','Bulk actions apply only to the selected language of each selected component.'=>'Бөлөх дьайыылар талыллыбыт компоненнар талыллыбыт тылларыгар эрэ туттуллаллар.','Bulk actions apply to every matching language of each selected component.'=>'Бөлөх дьайыылар талыллыбыт хас биирдии компоненка сөп түбэһэр бары тылга туттуллаллар.','Bulk download:'=>'Мунньуллубут хачайдааһын:','Bulk request:'=>'Мунньуллубут көрдөбүл:','Bulk update:'=>'Мунньуллубут саҥардыы:','Bundled with the plugin'=>'Плагины кытта кэлбит','Bundled with the theme'=>'Тематын кытта кэлбит','By clicking Enable, you agree to send the information listed above to Babilim.'=>'«Холбоо» диэҥҥэ баттаатаххына, үөһэ ыйыллыбыт сибидиэнньэни Babilim-ҥа ыытарга сөбүлэһэҕин.','By continuing you confirm that you have the right to upload this component.'=>'Салгыыргар, бу компоненты ыытар быраабыҥ баарын бигэргэтэҕин.','Cancel'=>'Тохтот','Category'=>'Категория','Check again'=>'Хат көр','Check again now'=>'Билигин өссө төгүл бэрэбиэркэлээ','Checkout is not available for this site right now.'=>'Билигин бу сайтка төлөбүр ыытыыта кыаллыбат.','Choose'=>'Талыы','Choose a category…'=>'Категорияны талыы…','Choose a language'=>'Тылы тал','Choose a language…'=>'Тылы талыҥ…','Clear filters'=>'Сиидэлэри сот','Close'=>'Сап','Component'=>'Компонент','Confirm'=>'Бигэргэт','Conflicting keys'=>'Мөккүһэр күлүүстэр','Continue'=>'Салгыы','Continue next batch (%d left)'=>'Аныгыскы пакеты салгыы (%d хаалла)','Continuing…'=>'Салгыыр…','Could not back up %s before replacing it.'=>'%s солбуйарга диэри хос копиятын оҥорорго кыаллыбата.','Could not create the package archive.'=>'Пакет архыыба оҥоһуллубата.','Could not determine active components; the existing merged index was left unchanged.'=>'Актыыбынай компоненнары быһаарар кыах суох; баар холбоммут индекс уларыйбакка хаалла.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Туруоруллубут плагиннары/тематтары быһаарар кыах суох; ыраастааһын туораттарыллыбыта, туох даҕаны сотуллубата.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Сервистан WordPress.org локаллар толору испииһэгин киллэрэр кыаллыбата, ол иһин билигин атын тылы эбэр сатаммат.','Could not move %s into place.'=>'%s миэстэтигэр көһөрүү кыаллыбата.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' локалга холбоммут индексы миэстэтигэр уурары кыайбата; урукку сулууспалыыр индекс (баар буоллаҕына) аҥаара уларыйбыт курдук хаалбакка устулунна. Кэлэр ситиһиилээх хат тутуллуор диэри бу локалга Ыйыллыбатах домен эбиитэ биэриллиэ суоҕа.','Could not open zip: %s'=>'zip аһан кыайбатым: %s','Could not prepare %s for rollback.'=>'%s төттөрү эргитиигэ бэлэмнииргэ кыаллыбата.','Could not read %s back after moving it into place.'=>'%s миэстэтигэр көһөрбүтүн кэннэ хат ааҕарга кыаллыбата.','Could not read: %s'=>'Ааҕыллыбата: %s','Could not restore the purchase: %s'=>'Атыыны төнүннэрэр кыаллыбата: %s','Could not show a new restore code: %s'=>'Саҥа төттөрү төрүтүнэр коду көрдөрбөтө: %s','Could not stage %s'=>'%s бэлэмнииргэ кыаллыбата','Could not stage default/%s'=>'default/%s бэлэмнээн туруорарга кыаллыбата','Could not start checkout: %s'=>'Төлөбүрү саҕалыы кыаллыбата: %s','Could not verify entry count for %s'=>'%s суруктар ахсаанын бэрэбиэркэлииргэ кыаллыбата','Could not write the downloaded package to disk.'=>'Хачайдаммыт пакеты дискэҕэ суруйар кыах суох.','Could not write the staged merged index.'=>'Бэлэмнэммит холбоммут индекси суруйан кыайбатым.','Current translation'=>'Билиҥҥи тылбаас','Custom overrides'=>'Бэйэ солбуйуохтара','Danger zone'=>'Кутталлаах зона','Default supplement entry count mismatch.'=>'Default эбии суруктар ахсаана сөп түбэспэтэ.','Delete all Babilim data on uninstall'=>'Туох баарын Babilim дааннайдарын устарыгар сот','Disable Babilim'=>'Babilim араарыы','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim-ы араарыах дуо? Туруоруллубут тылбаастар хаалаллар, ол эрээри ол кэнниттэн бэрэбиэркэ уонна хачайдааһын ыытыллыбат.','Don\'t share'=>'Үллэспэт','Download'=>'Хачайдааһын','Downloaded and installed.'=>'Хачайдаммыт уонна туруоруллубут.','Downloading…'=>'Хачайдана турар…','Downloads: %1$d/%2$d (%3$s)'=>'Хачайдааһыннар: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Хас биирдии компонент тыл аайы ыйыллыбатах домен эбиитигэр киллэрбит бэйэтин кылаата.','Enable Babilim'=>'Babilim-ы үлэҕэ киллэр','Enabling…'=>'Үлэҕэ киллэриллэр…','English (United States)'=>'Английскай (АХШ)','Entries'=>'Суруйуулар','Entry count mismatch for %s'=>'%s суруктар ахсаана сөп түбэспэтэ','Error reports'=>'Алҕас туһунан сибээстэр','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Туруоруллубут хас биирдии плагин/тема: слага, барыла, тиэкис домен(нар)а, wp.org испииһэгэр баарый-суоҕуй, бэйэтин киллэриллибит локальлара уонна ханнык локаллар туһугар Babilim тылбааһын туруорбуккун.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Бу сайтка туттуллар бары локаллар (сайт локала, туруоруллубут тыл пакеттара, кыттааччылар локаллара уонна илиинэн эбиллибиттэр). Ханнык даҕаны локал атыттартан туспа сыһыаннаспат.','Excluded'=>'Таһаарылынна','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Атын аттаах эбэтэр кэҥэтиилээх билэлэр киирбэттэр, оттон uploads, cache, logs, backup, data, vendor, node_modules уонна languages хаалбаһалар, саһаарыллыбыт билэлэр, ону тэҥэ биллэр кистэлэҥ билэлэр курдук аттаахтар (wp-config*, .env*, *.sql, *.log, *.pem, *.key) киирбэттэр. Куод билэлэрэ атын дьон көрүөхтэрин баҕарбатах тиэкистэрдээх эбэтэр дааннайдаах буолуохтарын сөп; саарбахтыыр буоллаххына чинчий. Сыансата кэлиитигэр маннык билэлэри төттөрү сотор.','Free'=>'Босхо','Free-plan slots'=>'Босхо тарифа слоттара','General'=>'Уопсай','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Бу киллэриллэн турдаҕына, устарыгар сайт идентификатын даҕаны сотор. Бу сайтка холбоммут төлөбүрдээх лицензия кэлин аптамаатынан эргиллибэт; ону төнүннэрээри Babilim өйөбүлүгэр %s аадырыска сибээстэһиэхтээххин.','Included'=>'Киллэриллибит','Included in index'=>'Индекска киирдэ','Install available translations automatically'=>'Баар тылбаастары аптамаатынан туруор','Installed'=>'Туруорулунна','Installed translations are kept, but no further checks or downloads will run.'=>'Туруоруллубут тылбаастар хаалаллар, ол эрээри ол кэнниттэн бэрэбиэркэ уонна хачайдааһын ыытыллыбат.','Installed · %s'=>'Туруорулунна · %s','Installed · built for %1$s, this site has %2$s'=>'Туруоруллубут · %1$s аналлаах, бу сайтка %2$s баар','Installed · built for %s'=>'Туруоруллубут · %s аналлаах','Installed · built for %s, all free-plan slots for this site are used'=>'Туруорулунна · %s анаан оҥоһуллубут, бу сайт босхо тарифа слоттара барыта туттулла тураллар','Installed · built for %s, new version failed'=>'Туруоруллубут · %s барылга аналлаах, саҥа барыла табыллыбата','Installed · built for %s, new version not covered by the free service plan'=>'Туруорулунна · %s анаан оҥоһуллубут, саҥа барыл босхо сыаҥҥа тарифҥа киирбэт','Installed · built for %s, new version scheduled'=>'Туруоруллубут · %s барылга аналлаах, саҥа барыла былааннаммыт','Installed · built for %s, translating the new version…'=>'Туруоруллубут · %s аналлаах, саҥа барылын тылбаастыы турар…','Installed · built for a different version'=>'Туруоруллубут · атын барылга аналлаах','Installed · built for a different version, all free-plan slots for this site are used'=>'Туруорулунна · атын барылга анаан оҥоһуллубут, бу сайт босхо тарифа слоттара барыта туттулла тураллар','Installed · built for a different version, new version failed'=>'Туруорулунна · атын биэрсийэҕэ оҥоһуллубут, саҥа биэрсийэ табыллыбата','Installed · built for a different version, new version not covered by the free service plan'=>'Туруорулунна · атын барылга анаан оҥоһуллубут, саҥа барыл босхо сыаҥҥа тарифҥа киирбэт','Installed · built for a different version, new version scheduled'=>'Туруоруллубут · атын барылга аналлаах, саҥа барыла былааннаммыт','Installed · built for a different version, translating the new version…'=>'Туруоруллубут · атын барылга аналлаах, саҥа барылын тылбаастыы турар…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Ону сервис хостинг ыытааччыта харыстыыр, тылбааһы оҥорорго AI модельтара ол дааннайы сыныйан туһаналлар.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Бэйэм тылбаас солбуйуохтарбын барытын ыраастыырга эбэтэр бу плагины устарга хаалар.','Language'=>'Тыл','Language:'=>'Тыл:','Languages'=>'Тыллар','Languages found on this site: %s.'=>'Бу сайтан көстүбүт тыллар: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Бүтэһик ыраастааһын %1$s: %2$d саҥа бэлиэтэммит, %3$d билэ устуллубут, %4$d сурук сотуллубут.','Maintenance'=>'Көрүү-харайыы','Maintenance status is not available right now.'=>'Көрүү-харайыы балаһыанньата билигин ылыллыбат.','Manifest unavailable: %s'=>'Манифест ыларга табыллыбат: %s','Negation reversed'=>'Аккаастааһын утары эргитиллибит','No'=>'Суох','No build is available to download for this locale.'=>'Бу локаль туһугар хачайдыыр build суох.','No cleanup has run yet.'=>'Ыраастааһын өссө ыытыллыбата.','No components match these filters. %s'=>'Бу сиидэлэргэ компоненнар сөп түбэспэттэр. %s','No components synced yet.'=>'Компоненттар өссө синхроннамматахтар.','No installed translation matches.'=>'Сөп түбэһэр туруоруллубут тылбаас суох.','No language is managed yet.'=>'Билигин ханнык да тыл салайыллыбат.','No pending challenge for this nonce.'=>'Бу nonce-қа кэтэһэр сорук суох.','No pending challenge to verify.'=>'Бигэргэтиэхтээх кэтэһэр сорук суох.','No plugins or themes found.'=>'Плагиннар эбэтэр тиэмэлэр көстүбэтэхтэр.','No previous build to roll back to.'=>'Төттөрү эргитэр иннинээҕи build суох.','No record for %s'=>'%s туһунан сурук суох','No site id is on file to rotate a token for.'=>'Токены уларытарга бигэргэммит сайт идентификатора суох.','No — component inactive'=>'Суох — компонент актыыбынайа суох','No — component removed'=>'Суох — компонент сотулунна','No — installed version differs from the active one'=>'Суох — туруоруллубут бэрсиэ актыыбынай бэрсиэттэн атын','Not a valid server_build_id: %s'=>'Сөп server_build_id буолбатах: %s','Not covered by the free service plan'=>'Босхо сыаҥҥа тарифҥа киирбэт','Not installed'=>'Туруорулла илик','Not registered yet'=>'Өссө регистрацияламмата','Not supported'=>'Өйөнмөт','Not verified'=>'Бигэргэтиллибэтэх','Note (optional)'=>'Бэлиэтээһин (ирдэммэт)','Nothing to choose.'=>'Талаллыахтаах суох.','Nothing to confirm.'=>'Бигэргэтиэхтээх суох.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Анаан этиллибэтэҕинэ араарыллыбыт: плагины устуу бу сайт идентификатын хаалларар, онон төттөрү туруоруу ону туттар кыахтаах.','One or more served files no longer match the manifest.'=>'Биир эбэтэр элбэх туттуллар билэ манифести кытта сөп түбэспэт буолла.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Бу сайтка биир төлөбүр: %1$s %2$s. Кэлэр бары тылбаас саҥардыылара киирэллэр. Төлөбүрү Paddle саҥа таб иһигэр ыытар.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Маны ситим администратора эрэ оҥорор, тоҕо диэтэххэ бу ситим бары сайтарыгар тэҥҥэ туттуллар тылбаас билэлэрэ уларыйаллар.','Only plugins and themes can be packaged.'=>'Плагиннары уонна тиэмэлэри эрэ пакетыыр кыах баар.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'WordPress.org-ка суох плагини эбэтэр тиэмэни хачайдааһыны бигэргэппиккэр эрэ: барыта .php уонна .js билэлэр, барыта block.json билэлэр, уонна ол сорох ис чааһын сүрүн хаалбаһыгар баар readme.txt, readme.md, style.css уонна theme.json, zip курдук, кистэлэҥ билэлэр курдук аттаахтар хаалларыллыбыттарын кэннэ.','Open Babilim settings'=>'Babilim туруорууларын ас','Original language'=>'Бастакы тыл','Original string'=>'Төрүт строка','Paid'=>'Төлөнөр','Partner'=>'Партнёр','Please check that your site can be reached from the internet, then try again.'=>'Сайтыҥ интэриниэттэн тиийиллэр буоларын бэрэбиэркэлээ, онтон хат боруобалаа.','Please choose a category for this report.'=>'Бу биллэриигэ категорияны тал.','Plugin'=>'Плагин','Plugin · %s'=>'Плагин · %s','Plugins'=>'Плагиннар','Preview'=>'Урутаан көрүү','Purchase restored. This site is now licensed.'=>'Ыллыы төттөрү төрүтүннэ. Бу сайт билигин лицензиялаах.','Re-parsed entry count did not match the built index.'=>'Хат ааҕыллыбыт суруктар ахсаана тутуллубут индекска сөп түбэспэтэ.','Re-verify'=>'Хат бигэргэт','Rebuild index now'=>'Индекси билигин саҥаттан оҥор','Refusing to write outside the Babilim language-file directory.'=>'Babilim тыл билэлэрин пааппатыттан тас суруйарга аккаастанабын.','Registration response was missing required fields.'=>'Регистрация хоруйугар наадалаах хонуулар суохтар этилэр.','Registration restarted.'=>'Регистрация төттөрү саҕаланна.','Remove'=>'Туорат','Remove everything Babilim installed'=>'Babilim туруорбутун барытын сотор','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim туруорбутун барытын сотор? Бу сайтка бары плагиннарга уонна тиэмэлэргэ Babilim туруорбут тыл билэлэрин барытын сотор.','Remove the %2$s translation of %1$s from this site?'=>'%1$s компоненын %2$s тылбааһын бу сайтан сотоҕут?','Removed %d installed component.'=>'%d туруоруллубут компонент сотулунна.' . "\0" . '%d туруоруллубут компонент сотулунна.','Removed after a failed integrity check'=>'Барыта тутуллубутун бэрэбиэркэлээһин кыайыллыбатаҕына устулунна','Removed.'=>'Сотуллубут.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Бу сайтка бары плагиннарга уонна тиэмэлэргэ Babilim туруорбут тыл билэлэрин барытын сотор.','Report a problem'=>'Кыһалҕаны иһитиннэр','Report translation'=>'Тылбаас туһунан сибээс','Request newer translation'=>'Саҥа тылбааһы көрдөө','Request translation'=>'Тылбаас көрдөө','Requestable'=>'Көрдөнүөн сөп','Requesting…'=>'Көрдөһөр…','Restart registration'=>'Регистрацияны саҥаттан саҕалаа','Restore code'=>'Төттөрү төрүтүнэр код','Restore purchase'=>'Ыллыыны төттөрү аҕал','Retry request'=>'Көрдөбүлү төттөрү ыыт','Roll back'=>'Төттөрү хайтар','Roll back and report'=>'Төттөрү хайтар уонна кыһалҕаны иһитиннэр','Roll back and send report'=>'Төттөрү эргит уонна отчуоту ыыт','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s компонеҥҥа %2$s тылбааһы иннинээҕи оҥоһууга төттөрү эргитиэххэ дуо?','Rolled back and reported.'=>'Төннөрүллүбүт уонна биллэриллибит.','Rolled back to the previous build.'=>'Мантан иннинээҕи build-ка төнүннэ.','Rolled back, but the report could not be sent: %s'=>'Төннөрүллүбүт, ол эрээри биллэриини ыытар табыллыбата: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Төттөрү эргитии \'%1$s\' (%2$s) билэни үрдүнэн суруйуо этэ, ол билигин атын туруоруллубут компонеҥҥа %3$s туттуллар; онон туох даҕаны уларыйбата.','Rotate-token response was missing site_token.'=>'Токены уларытыы хоруйугар site_token көстүбэтэ.','Save changes'=>'Уларытыылары харай','Scheduled, waiting to be processed'=>'Былааннаммыт, оҥоһуллуутун күүтэр','Search'=>'Көрдөө','Search components'=>'Компоненнары көрдөө','Search the installed translations'=>'Туруоруллубут тылбаастары көрдөө','Select all'=>'Барытын талыы','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Аҕыйах компоненты талыҥ: биир ыытыыга %1$d дьайыыттан ордубат (эн %2$d талбыккын).','Send report'=>'Репорт ыыт','Service plan'=>'Сыаҥҥа тарифа','Settings'=>'Туруоруулар','Share error reports'=>'Алҕас туһунан сибээстэри үллэстии','Share this report'=>'Бу сибээһи үллэстии','Show a new restore code'=>'Саҥа төттөрү төрүтүнэр коду көрдөр','Show the "Report translation" entry in the admin toolbar'=>'Дьаһалтаҕа үстүрүмүөн паанелигэр "Report translation" пууҥҥу көрдөр','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Бу компонент тиэкизин сорох чааһа ааптарынан кодка бигэтик суруллубут, ол иһин тыл пакетынан тылбаастаныа суоҕа.','Status'=>'Балаһыанньа','Status unknown'=>'Туруга биллибэт','String context'=>'Строка контекста','Suggested translation'=>'Туруорууллубут тылбаас','Supplementary translation index'=>'Эбии тылбаас индекса','Supplementary translation index rebuilt.'=>'Эбии тылбаас индекса төттөрү оҥоһулунна.','Supplementary translation maintenance'=>'Эбии тылбааһы көрүү-харайыы','Supplementary translations'=>'Эбии тылбаастар','Sweep aborted without orphaning anything: %s.'=>'Ыраастааһын ханнык даҕаны хаалбыты бэлиэтээбэккэ тохтотулунна: %s.','Sweep complete: %d file deleted.'=>'Сууйуу бүттэ: %d билэ сотулунна.' . "\0" . 'Сууйуу бүттэ: %d билэ сотулунна.','Sweep now'=>'Билигин сууй','Sync complete.'=>'Синхроннааһын бүттэ.','Thank you. Your report was sent.'=>'Баһыыба. Биллэрииҥ ыытыллыбыт.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Бу компонент маннык сайтка туруоруллубатах, ол иһин тылбаастатарга көрдөһүү ыытыллыбат.','That does not look like a restore code.'=>'Ити төттөрү төрүтүнэр кода буолбатах.','That is not a valid WordPress locale code. Nothing was saved.'=>'Бу WordPress локалын сөптөөх кода буолбатах. Туох да хараллыбата.','That is not a valid build identifier.'=>'Бу чахчы оҥоһуу идентификатора буолбатах.','The change could not be recorded in the translation index; please try again.'=>'Уларыйыыны тылбаас индексыгар суруйар кыаллыбата; хат холонон көр.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Ыраастааһын ыытылынна, ол эрээри сорох уларытыылар тылбаас индексигэр суруллубатылар; кэлэр ыраастааһын ону хат боруобалыыр.','The component has no files that can be uploaded.'=>'Бу сорох ис чааһыгар хачайданар билэлэр суохтар.','The component is not inside the plugins or themes directory.'=>'Компонент плагиннар эбэтэр темалар директорияларын иһигэр суох.','The component\'s main file was not found.'=>'Компонент сүрүн билэтэ көстүбэтэ.','The download response was missing a usable location.'=>'Хачайдааһын хоруйугар туттар сөптөөх аадырыс көстүбэтэ.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Бу пуункт паанелы арыйар: онно Babilim бу сайтка туруорбут тылбаастарын көрдүөххэ уонна кинилэртэн биирин туһунан сыыһатын биллэриэххэ сөп.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" хонуута наһаа уһун: %2$d бэлиэлээх, лимиит — %3$d. Туох да ыытыллыбата; кылгатан, хат гынан сатаа.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Биэриллибит \'%1$s\' домен пакет манифегын бэйэтин \'%2$s\' слага да, \'%3$s\' text_domain-а да буолбатах.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' холбоммут индекса саҥаттан тутулунна, ол эрээри тылбаас индекса ону сурукка киллэрбэтэ; кэлэр тутуу эмиэ боруобалыыр.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Оригинал тиэкис уонна онтон оҥоһуллубут тылбастар биир версияны туруорар атын сайтарга биэриллиэхтэрэ.','The package declares no main translation file.'=>'Пакекка тылбаас сүрүн билэтэ ыйыллыбатах.','The package has no %s for its own text domain.'=>'Пакетка бэйэтин тиэкис домена иһин %s суох.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Пакет манифегын \'%1$s\' көрүҥэ көрдөммүт \'%2$s\' көрүҥҥэ сөп түбэспэт.','The package produced no servable main translation file.'=>'Пакет туттуллар кыахтаах сүрүн тылбаас билэтин оҥорбото.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Пакет тиэкис домена \'%1$s\' бу сайтка баар компонент копиятын (\'%2$s\') кытта сөп түбэспэт, ол иһин туруорулла иликтэ.','The packaged component could not be read.'=>'Пакеттаммыт компонент ааҕыллыбата.','The registration challenge is not in the expected form.'=>'Регистрация бигэргэтэр сорудаҕа күүтүллэр форматка сөп түбэспэт.','The report could not be sent.'=>'Сибээс ыытыллыбата.','The search could not be completed.'=>'Көрдөөһүн оҥоһуллубата.','The service asked this site to wait before syncing again.'=>'Сервис бу сайтан төттөрү синхронизацияламмакка кэтэһэргэ көрдөстө.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Сулууспа эн сайтыҥҥа тиийбэтэ. Баҕар, брандмауэр, көмүскэл плагин эбэтэр хостинг ирдэбилэ көрдөбүлү тохтотор; /wp-json/babilim/v1/challenge диэн көрдөбүллэри көҥүллээ.','The service\'s upload offer was incomplete.'=>'Сервис туттарыы туһунан этиитэ толорута суох этэ.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'\'%1$s\' (%2$s) тиэкис домена атын туруоруллубут компонеҥҥа (%3$s) хайыы-үйэ туттуллар; туох да туруоруллубата.','The upload is kept until you ask Babilim to delete it.'=>'Ыытыллыбыт билэ Babilim-тан ону сотон биэрэригэр көрдөһүөххүн диэри харалла сытар.','Theme'=>'Тема','Theme · %s'=>'Тиэмэ · %s','Themes'=>'Тиэмэлэр','There is no upload in progress.'=>'Билигин билэ ыытыллыбат.','There is no upload waiting for confirmation.'=>'Бигэргэтиини кэтэһэр ыытыы суох.','These are the languages this site uses. You can change them in %s.'=>'Бу сайт туттар тыллара бу. Эһиги ону %s иһигэр уларыталыаххытын сөп.','These fields will be sent:'=>'Бу хонуулар ыытыллыахтара:','This build is not one this site currently knows about for this component/locale.'=>'Бу сайт бу компонент/тыл туһугар бу оҥоһуллууну билбэт.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Бу компонент барылын нүөмэрин ыйбатах, ол иһин тылбаастатарга көрдөһүү ыытыллыбат.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Бу компонент сервис ылар кээмэйиттэн улахан, онон ыытыллыбат.','This component was already uploaded. Babilim is checking it now.'=>'Бу компонент урут ыытыллыбыт. Babilim билигин бэрэбиэркэлиир.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Бу компонент барылын нүөмэрэ %d бэлиэттэн уһун, Babilim итини салайар кыаҕа суох, онон тылбаастатарга көрдөһүү ыытыллыбат.','This issues a new restore code and the previous one stops working. Continue?'=>'Бу саҥа төттөрү төрүтүнэр коду биэрэр, урукку кода үлэлиирин бүтэрэр. Салгыах дуо?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Бу ситимҥэ сайт наһаа элбэх, онон барытын биирдии-биирдии көрөн тахсар кыах суох; сорох сайт плагин сотуллубутугар Babilim идентификатын сотор гына туруорулуннаҕа. Ол сайтка холбоммут төлөбүрдээх лицензия кэлин аптамаатынан эргиллибэт; Babilim өйөбүлэ %s аадырыска сибээстэһиэхтээххин. Идентификаттары хаалларарга «Cancel» диэни баттаа, хас биирдии сайт Babilim туруорууларыгар "Туох баарын Babilim дааннайдарын устарыгар сот" бэлиэни ыл, онтон плагины өссө төгүл арахсыт. Ол гынан баран арахсытыаххын баҕараҕын дуо?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Бу плагин бэйэтин барылын көрдөрөр, онон сервис плагин олус эргэр буоллаҕына, ону саҥардыҥ диэн этиэн сөп.','This report does not name a valid plugin or theme and locale.'=>'Бу отчуот сөп буолар плагини эбэтэр тиэмэни уонна локалы ыйбат.','This report does not name an installed string.'=>'Бу отчуот туруорүллүбүт строканы ыйбат.','This report is missing a valid build to report against.'=>'Бу рапорка сыһыаннаһар сөптөөх build суох.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Бу сибээс GitHub-ка аһаҕастык бэчээттэниэ уонна үһүс өттүлэргэ хараллыан сөп.','This restore code was not recognised for this site.'=>'Бу төттөрү төрүтүнэр код бу сайтка биллибэтэ.','This site already has an active registration that can no longer be recovered automatically.'=>'Бу сайтка аптамаатынан төнүннэриллибэт буолбут актыыбынай регистрация баар.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Бу сайтка %1$d компонент %2$d тылга баар, ол %3$d бэрэбиэркэ пакетын эрэйэр; Babilim биир ыытыыга %4$d эрэ толорор. Туруорууларга салайыллар тыллары кыччат эбэтэр туттуллубат плагиннары уонна тиэмэлэри араар, ол кэннэ Билигин өссө төгүл бэрэбиэркэлээ диэни батт.','This site has no purchase to show a code for.'=>'Бу сайтка код көрдөрөр атыылаһыы суох.','This site is already licensed. Reload the page.'=>'Бу сайт номнуо лицензияламмыт. Сирэйи хат хачайдаа.','This site is not registered with Babilim yet.'=>'Бу сайт Babilim-га өссө регистрацияламмата.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Бу сайт биир синхроннааһыҥҥа сервис ылар кээмэйиттэн ааста, онон сорох пууннар хаалбыттара: %1$d компонент уонна %2$d локаль.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Бу сайт multisite ситим чааһа, ол иһин саҥа тылбаастары аптамаатынан туруорбат. Баар туруоруллубут тылбаастар өссө даҕаны саҥардыллаллар.','This site is verified.'=>'Бу сайт бигэргэннэ.','This site must be verified first.'=>'Бу сайт бастаан бигэргэтиллиэхтээх.','This site\'s URL, so the service can verify you own it.'=>'Бу сайт URL-а, сервис эн бу сайт хаһаайына буоларгын бигэргэтэригэр.','This site\'s address is too long for Babilim to register.'=>'Бу сайт аадырыһа наһаа уһун, Babilim бэлиэтиир кыаҕа суох.','This site\'s configured locale.'=>'Бу сайт туруорбут локала.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Бу сайка туруоруллубут аһаҕас ключ, көрдөбүллэр чахчы бу сайтан кэлбиттэрин туоһулуур. Аһаҕас аҥаара эрэ ыытыллар.','This site\'s locale code is not one Babilim can register.'=>'Бу сайт локаль кодун Babilim регистрациялыан кыаҕа суох.','This string can\'t be reported from this site.'=>'Бу строка туһунан бу сайтан сибээс ыытар табыллыбат.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Бу строка бу сайтка туруоруллубут тылбаастарга суох. Хат көрдөө уонна испииһэктэн тал.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Бу тылбаас эн көрдөөбүтүҥ кэннэ саҥардылынна. Хат көрдөө уонна строканы саҥа испииһэктэн тал.','To translate this component, Babilim needs its source.'=>'Бу компоненты тылбаастыырга Babilim-ҥа кини төрүт кода наада.','Too many attempts. Try again tomorrow.'=>'Наһаа элбэх холонуу. Сарсын хатылаа.','Too many reports today. Try again tomorrow.'=>'Бүгүн сибээс наһаа элбэх. Сарсын төттөрү боруобалаа.','Too many requests.'=>'Ыйытыылар наһаа элбэхтэр.','Toolbar'=>'Үстүрүмүөн паанелэ','Translating…'=>'Тылбаастыы турар…','Translation does not load'=>'Тылбаас хачайдамматах','Translation failed'=>'Тылбаас ситэ барбата','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'%s иһигэр уурбут тылбаас билэлэриҥ Babilim билэлэриттэн ордук суолталаахтар. Маны сүүрдүбэтэххэ, олор хаалаллар.','Translation requested.'=>'Тылбаас көрдөһүллүбүт.','Translations'=>'Тылбаастар','Type'=>'Көрүҥ','Type at least 2 characters to search.'=>'Көрдүүргэ 2-тэн итэҕэһэ суох бэлиэни суруй.','Unexpected HTTP %d response.'=>'Күүппэтэх HTTP %d хоруй.','Uninstall'=>'Устарыы','Unknown kind: %s'=>'Биллибэт көрүҥ: %s','Unsafe domain: %s'=>'Бигэ суох домен: %s','Unsafe locale: %s'=>'Куттала баар локал: %s','Unsafe slug: %s'=>'Куттала баар slug: %s','Unsafe text_domain: %s'=>'Куттала баар text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'20-тэн ордубат күүтэр диагностика түбэлтэлэрэ (холобур, барыта тутуллубутун бэрэбиэркэлээһини ааспатах билэ); хас биирдиитэ код, компонент уонна локаль эрэ, ханнык да тиэкис эбэтэр тылбаастаммыт тиэкис суох.','Update'=>'Саҥардыы','Update available'=>'Саҥардыы баар','Updates'=>'Саҥардыылар','Updating…'=>'Саҥардылла турар…','Upgrade this site'=>'Бу сайты үрдэт','Upload and request'=>'Ыыт уонна көрдөбүл ыыт','Upload cancelled.'=>'Ыытыы тохтотулунна.','Upload complete — translation requested.'=>'Ыытыы бүттэ — тылбаас көрдөһүллүбүт.','Upload expired before it finished'=>'Ыытыы түмүктэнэ иликкэ болдьоҕо ааста','Upload in progress — continue or cancel'=>'Хачайдааһын бара турар — салгаа эбэтэр боторуй','Upload this component?'=>'Бу компоненты ыытыах дуо?','Upload was not accepted'=>'Хачайдааһын ылыныллыбата','Uploading'=>'Таһаарыллар','Uploading part %1$d of %2$d…'=>'%2$d чааһыттан %1$d-с чааһы ыытыы…','Uploading…'=>'Таһаарыллар…','Verified'=>'Бигэргэтиллибит','Verify response was missing site_token.'=>'Бигэргэтии хоруйугар site_token көстүбэтэ.','Version %s'=>'Биэрсийэ %s','What is sent when Babilim checks this site'=>'Babilim бу сайты чинчийэригэр туох ыытылларый','What is sent when you enable Babilim'=>'Babilim-ы үлэҕэ киллэрдэххинэ тугу ыытарый','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Babilim иһигэр туох эмит алдьаннаҕына, алҕас туһунан сибээһи Babilim сулууспатыгар ыыт, ол GitHub-ка аһаҕас ыйытык быһыытынан бэчээттэниэ. Сибээс бу сайтан ыытыллар, Babilim сулууспатыгар атын бары ыйытыктар курдук биир тэҥ бигэргэтиинэн. Сулууспа GitHub-ка аһаҕас ыйытык быһыытынан алҕас кодун уонна барылларын эрэ бэчээттиир; аһаҕас ыйытыкка сайт аадырыһа, иһинээҕитэ эбэтэр билэлэр суолларо суохтар. Анаан этиллибэтэҕинэ сабыылаах.','Where you saw this (optional)'=>'Маны ханна көрбүккүн (ирдэммэт)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Бу холбоноро турдаҕына, сиэрбис эн салайар тылларыҥ иһин баар диэн ыйбыт тылбаастара суукканы иккитэ синхроннааһын кэмигэр туруорулла тураллар.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Бу контекска сыыһа','Wrong meaning'=>'Сыыһа суолтата','Wrong plural form'=>'Хас да ахсаан сыыһа forma','Wrong term'=>'Сыыһа термин','Yes'=>'Сөп','You are not allowed to do this.'=>'Эн маны оҥороргор көҥүл суох.','Your PHP version, for compatibility.'=>'PHP барыла, сөп түбэһиитин туһугар.','Your WordPress version, to serve compatible translation files.'=>'WordPress барыла, сөп түбэһэр тылбаас билэлэрин биэрэр туһугар.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Эйиги саҥа Төттөрү төрүтүнэр кодуҥ: %s. Ону бигэ сиргэ харыстаа — урукку код билигин үлэлээбэт.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Эн сибээһиҥ AI модельтарынан аптамаатынан оҥоһуллар уонна атын сайтар иһин бу тылбааһы тупсарыан сөп.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Сайтыҥ хоруйдаата, ол эрээри кэтэһиллибэтэх хоруйу биэрдэ. REST API атын плагинынан уларыллыбыт эбэтэр ол endpoint кэштэммит буолуон сөп; /wp-json/babilim/v1/challenge-ы кэштээһинтэн уонна уларытыыттан тэйитиҥ.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Эн сайтыҥ наһаа уһуннук хоруйдаата. Кэлин хат боруобалаа, хостуҥ наһаа бытаан эбэтэр ыараабыт буолуон сөп, ону көр.','Zip has no manifest.json.'=>'Zip иһигэр manifest.json суох.','Zip is missing expected default file: %s'=>'Zip иһигэр кэтэһиллибит default билэ суох: %s','Zip is missing expected file: %s'=>'Zip иһигэр кэтэһиллибит билэ суох: %s','_manifest.json has an unexpected structure'=>'_manifest.json тутула кэтэһиллибэтэх','could not read _manifest.json: %s'=>'_manifest.json ааҕарга кыаллыбата: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest \'%s\' суох эбэтэр сыыһа.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest иһигэр \'server_build_id\' сөптөөх оҥоһуу идентификатора буолбатах.','failed to parse _manifest.json: %s'=>'_manifest.json парсингтаммата: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'салайыллар %2$d компоненттартан %1$d хаалбыт (хаһаайына суох) буолуо (аҥарыттан элбэх)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'салайыллар %1$s компонент барыта хаалыаҕа (хаһаайына суох) (%2$d иһигэр %2$d)','l10n.php entry count mismatch for %s'=>'%s l10n.php суруйуулар ахсаана сөп түбэспэтэ','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json \'default_domain_entries\' сыыһа.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json \'default_domain_files\' сыыһа.','manifest.json in the zip is not valid JSON.'=>'zip иһинээҕи manifest.json сөп JSON буолбатах.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json иһигэр \'%s\' суох эбэтэр сыыһа.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json \'build_no\' суох эбэтэр сыыһа.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json \'entries\' суох эбэтэр сыыһа.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json \'extra_domains\' суох эбэтэр сыыһа.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json \'files\' суох эбэтэр сыыһа.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json иһигэр \'%s\' күүтүллэр суолтаҕа сөп түбэспэт.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json иһигэр \'contract\' сөптөөх барыла устуруока буолбатах.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json \'kind\' \'plugin\' эбэтэр \'theme\' буолуохтаах.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json иһигэр \'server_build_id\' сөптөөх оҥоһуу идентификатора буолбатах.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json \'status\' \'published\' буолуохтаах.','nonce must be a hexadecimal string.'=>'nonce уон алталыын (hexadecimal) суруллубут устуруока буолуохтаах.','per day'=>'күн аайы','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s sha256 сөп түбэспэтэ','sha256 mismatch for default/%s'=>'default/%s sha256 сөп түбэспэтэ','component kind in the sweep brake messageplugin'=>'плагин','component kind in the sweep brake messagetheme'=>'тема','problem report categoryOther'=>'Атын','translation statusAvailable'=>'Баар','translation statusInstalled'=>'Туруоруллубут']];